#include <string>
#include <algorithm>
#include <cmath>
using namespace std;

class Solution {
public:
    int mirrorDistance(int n) {
        string s = to_string(n);
        reverse(s.begin(), s.end());
        int rev_n = stoi(s);
        return abs(n - rev_n);
    }
};

class Solution {
    public int mirrorDistance(int n) {
        String s = new StringBuilder(String.valueOf(n)).reverse().toString();
        int revN = Integer.parseInt(s);
        return Math.abs(n - revN);
    }
}

var mirrorDistance = function(n) {
    const revN = parseInt(String(n).split('').reverse().join(''), 10);
    return Math.abs(n - revN);
};
